    38	            BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.type());
    39	            return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
    40	        }
    41	        int nights = 0;
    42	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    43	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
